1	package core
2	
3	import (
4		"context"
5		"fmt"
6		"slices"
7		"strings"
8		"time"
9	
10		"github.com/tedkulp/drops/internal/model"
11	)
12	
13	// BlockedIssue pairs one candidate with its still-open blockers.
14	type BlockedIssue struct {
15		Issue     model.Issue `json:"issue"`
16		BlockedBy []model.ID  `json:"blocked_by"`
17	}
18	
19	// Ready returns the live, non-deferred Issues with no open blocks edge, over
20	// the candidate set filter names. An unset filter.Statuses means the actionable
21	// statuses, open and in_progress, so a caller that does not ask about status
22	// gets everything it could pick up rather than only what nobody has started.
23	func (core *Core) Ready(ctx context.Context, filter IssueFilter) ([]model.Issue, error) {
24		limit := filter.Limit
25		candidates, err := core.candidates(ctx, filter)
26		if err != nil {
27			return nil, err
28		}
29		blockers, err := core.OpenBlockers(ctx)
30		if err != nil {
31			return nil, err
32		}
33		now := core.currentTime()
34		ready := make([]model.Issue, 0, len(candidates))
35		for _, issue := range candidates {
36			if deferred(issue, now) || len(blockers[issue.ID]) != 0 {
37				continue
38			}
39			ready = append(ready, issue)
40			if limit > 0 && len(ready) == limit {
41				break
42			}
43		}
44		return ready, nil
45	}
46	
47	// Blocked returns the exact complement of Ready over the same live,
48	// non-deferred candidates, and reads filter.Statuses the same way. So the two
49	// partition one set between them: every actionable Issue is in exactly one.
50	func (core *Core) Blocked(ctx context.Context, filter IssueFilter) ([]BlockedIssue, error) {
51		limit := filter.Limit
52		candidates, err := core.candidates(ctx, filter)
53		if err != nil {
54			return nil, err
55		}
56		blockers, err := core.OpenBlockers(ctx)
57		if err != nil {
58			return nil, err
59		}
60		now := core.currentTime()
61		blocked := make([]BlockedIssue, 0)
62		for _, issue := range candidates {
63			if deferred(issue, now) || len(blockers[issue.ID]) == 0 {
64				continue
65			}
66			blocked = append(blocked, BlockedIssue{Issue: issue, BlockedBy: append([]model.ID(nil), blockers[issue.ID]...)})
67			if limit > 0 && len(blocked) == limit {
68				break
69			}
70		}
71		return blocked, nil
72	}
73	
74	// candidates is the row set Ready and Blocked partition: the Issues the filter
75	// names, unlimited so the limit applies to the answer rather than to the pool.
76	// The default lives here, once, so the two verbs cannot disagree about what an
77	// unstated status means.
78	//
79	// That default is `list`'s: open AND in_progress. Open alone left the Issue you
80	// had started in neither answer — `ready` could not offer you the work you were
81	// already doing, and `blocked` could not tell you what it was waiting on — so
82	// the two verbs summed to less than the live set they claim to partition
83	// (8bbam). Closed stays out: a finished Issue is neither actionable nor stuck.
84	func (core *Core) candidates(ctx context.Context, filter IssueFilter) ([]model.Issue, error) {
85		if len(filter.Statuses) == 0 {
86			filter.Statuses = []model.Status{model.StatusOpen, model.StatusInProgress}
87		}
88		filter.Limit = 0
89		return core.store.Issues(ctx, filter)
90	}
91	
92	// OpenBlockers maps each live, non-terminal Issue that still has an unfinished
93	// blocker to that Issue's open blocker ids, ascending. An Issue with no open
94	// blocker is absent rather than present and empty, so len(map[id]) is the
95	// blocked-by count for any id at all.
96	//
97	// It spans the whole store in one pair of reads and takes no filter, which is
98	// deliberate on both counts. A pane annotating a row set needs one call per
99	// refresh, never one per row; and a blocker outside the caller's scope still
100	// blocks, so a scoped map would under-report. The cost is therefore the whole
101	// store's, not the scope's: two reads and 4.9ms, best of 20, over the
102	// 1025-issue corpus, which keys 13 Issues (measured for qy3de.8).
103	func (core *Core) OpenBlockers(ctx context.Context) (map[model.ID][]model.ID, error) {
104		issues, err := core.store.Issues(ctx, IssueFilter{IncludeTombstoned: true})
105		if err != nil {
106			return nil, err
107		}
108		terminal := make(map[model.ID]bool, len(issues))
109		for _, issue := range issues {
110			terminal[issue.ID] = issue.Tombstone == model.Tombstoned || issue.Status == model.StatusClosed
111		}
112		dependencies, err := core.store.Dependencies(ctx)
113		if err != nil {
114			return nil, err
115		}
116		blockers := make(map[model.ID][]model.ID)
117		for _, dependency := range dependencies {
118			if dependency.Tombstone == model.Tombstoned || dependency.Type != model.DepBlocks {
119				continue
120			}
121			if terminal[dependency.FromID] {
122				continue
123			}
124			isTerminal, known := terminal[dependency.ToID]
125			if !known || !isTerminal {
126				blockers[dependency.FromID] = append(blockers[dependency.FromID], dependency.ToID)
127			}
128		}
129		return blockers, nil
130	}
131	
132	func deferred(issue model.Issue, now time.Time) bool {
133		if issue.DeferredUntil == nil {
134			return false
135		}
136		until, err := issue.DeferredUntil.Time()
137		return err == nil && until.After(now)
138	}
139	
140	// UnblockImpacts reports how many open candidates each named blocker alone
141	// prevents from becoming ready.
142	func (core *Core) UnblockImpacts(ctx context.Context, ids []model.ID) (map[model.ID]int, error) {
143		blockers, err := core.OpenBlockers(ctx)
144		if err != nil {
145			return nil, err
146		}
147		wanted := make(map[model.ID]struct{}, len(ids))
148		impact := make(map[model.ID]int, len(ids))
149		for _, id := range ids {
150			wanted[id], impact[id] = struct{}{}, 0
151		}
152		for _, open := range blockers {
153			if len(open) != 1 {
154				continue
155			}
156			if _, ok := wanted[open[0]]; ok {
157				impact[open[0]]++
158			}
159		}
160		return impact, nil
161	}
162	
163	// LongestBlockerChain returns the deepest simple path of open blockers, with id
164	// first. Cycles terminate at the first repeated node.
165	func (core *Core) LongestBlockerChain(ctx context.Context, id model.ID) ([]model.ID, error) {
166		if _, err := core.store.Issue(ctx, id); err != nil {
167			return nil, err
168		}
169		graph, err := core.OpenBlockers(ctx)
170		if err != nil {
171			return nil, err
172		}
173		onPath := map[model.ID]bool{}
174		var walk func(model.ID) []model.ID
175		walk = func(node model.ID) []model.ID {
176			if onPath[node] {
177				return nil
178			}
179			onPath[node] = true
180			defer func() { onPath[node] = false }()
181			best := []model.ID{}
182			for _, blocker := range graph[node] {
183				if candidate := walk(blocker); len(candidate) > len(best) {
184					best = candidate
185				}
186			}
187			return append([]model.ID{node}, best...)
188		}
189		return walk(id), nil
190	}
191	
192	// DependencyCycles returns canonical cycles of live blocks edges.
193	func (core *Core) DependencyCycles(ctx context.Context) ([][]model.ID, error) {
194		dependencies, err := core.store.Dependencies(ctx)
195		if err != nil {
196			return nil, err
197		}
198		graph := map[model.ID][]model.ID{}
199		for _, dependency := range dependencies {
200			if dependency.Type == model.DepBlocks && dependency.Tombstone == model.Live {
201				graph[dependency.FromID] = append(graph[dependency.FromID], dependency.ToID)
202			}
203		}
204		for node := range graph {
205			slices.Sort(graph[node])
206		}
207		cycles := [][]model.ID{}
208		state := map[model.ID]uint8{}
209		stack := []model.ID{}
210		position := map[model.ID]int{}
211		var visit func(model.ID)
212		visit = func(node model.ID) {
213			state[node], position[node] = 1, len(stack)
214			stack = append(stack, node)
215			for _, next := range graph[node] {
216				if state[next] == 0 {
217					visit(next)
218				} else if state[next] == 1 {
219					// One cycle per back edge, and no two back edges can yield
220					// the same one: distinct back edges end at distinct stack
221					// positions, and the (from_id, to_id, dep_type) primary key
222					// forbids a repeated edge. So no de-duplication is needed
223					// here, and a guard for it would be a branch no input reaches.
224					cycles = append(cycles, canonicalCycle(append([]model.ID(nil), stack[position[next]:]...)))
225				}
226			}
227			stack = stack[:len(stack)-1]
228			delete(position, node)
229			state[node] = 2
230		}
231		nodes := make([]model.ID, 0, len(graph))
232		for node := range graph {
233			nodes = append(nodes, node)
234		}
235		slices.Sort(nodes)
236		for _, node := range nodes {
237			if state[node] == 0 {
238				visit(node)
239			}
240		}
241		slices.SortFunc(cycles, func(left, right []model.ID) int {
242			return strings.Compare(fmt.Sprint(left), fmt.Sprint(right))
243		})
244		return cycles, nil
245	}
246	
247	func canonicalCycle(cycle []model.ID) []model.ID {
248		if len(cycle) == 0 {
249			return cycle
250		}
251		min := 0
252		for i := 1; i < len(cycle); i++ {
253			if cycle[i] < cycle[min] {
254				min = i
255			}
256		}
