package core

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"time"

	"github.com/tedkulp/drops/internal/model"
)

// BlockedIssue pairs one candidate with its still-open blockers.
type BlockedIssue struct {
	Issue     model.Issue `json:"issue"`
	BlockedBy []model.ID  `json:"blocked_by"`
}

// Ready returns the live, non-deferred Issues with no open blocks edge, over
// the candidate set filter names. An unset filter.Statuses means the actionable
// statuses, open and in_progress, so a caller that does not ask about status
// gets everything it could pick up rather than only what nobody has started.
func (core *Core) Ready(ctx context.Context, filter IssueFilter) ([]model.Issue, error) {
	limit := filter.Limit
	candidates, err := core.candidates(ctx, filter)
	if err != nil {
		return nil, err
	}
	blockers, err := core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}
	now := core.currentTime()
	ready := make([]model.Issue, 0, len(candidates))
	for _, issue := range candidates {
		if deferred(issue, now) || len(blockers[issue.ID]) != 0 {
			continue
		}
		ready = append(ready, issue)
		if limit > 0 && len(ready) == limit {
			break
		}
	}
	return ready, nil
}

// Blocked returns the exact complement of Ready over the same live,
// non-deferred candidates, and reads filter.Statuses the same way. So the two
// partition one set between them: every actionable Issue is in exactly one.
func (core *Core) Blocked(ctx context.Context, filter IssueFilter) ([]BlockedIssue, error) {
	limit := filter.Limit
	candidates, err := core.candidates(ctx, filter)
	if err != nil {
		return nil, err
	}
	blockers, err := core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}
	now := core.currentTime()
	blocked := make([]BlockedIssue, 0)
	for _, issue := range candidates {
		if deferred(issue, now) || len(blockers[issue.ID]) == 0 {
			continue
		}
		blocked = append(blocked, BlockedIssue{Issue: issue, BlockedBy: append([]model.ID(nil), blockers[issue.ID]...)})
		if limit > 0 && len(blocked) == limit {
			break
		}
	}
	return blocked, nil
}

// candidates is the row set Ready and Blocked partition: the Issues the filter
// names, unlimited so the limit applies to the answer rather than to the pool.
// The default lives here, once, so the two verbs cannot disagree about what an
// unstated status means.
//
// That default is `list`'s: open AND in_progress. Open alone left the Issue you
// had started in neither answer — `ready` could not offer you the work you were
// already doing, and `blocked` could not tell you what it was waiting on — so
// the two verbs summed to less than the live set they claim to partition
// (8bbam). Closed stays out: a finished Issue is neither actionable nor stuck.
func (core *Core) candidates(ctx context.Context, filter IssueFilter) ([]model.Issue, error) {
	if len(filter.Statuses) == 0 {
		filter.Statuses = []model.Status{model.StatusOpen, model.StatusInProgress}
	}
	filter.Limit = 0
	return core.store.Issues(ctx, filter)
}

// OpenBlockers maps each live, non-terminal Issue that still has an unfinished
// blocker to that Issue's open blocker ids, ascending. An Issue with no open
// blocker is absent rather than present and empty, so len(map[id]) is the
// blocked-by count for any id at all.
//
// It spans the whole store in one pair of reads and takes no filter, which is
// deliberate on both counts. A pane annotating a row set needs one call per
// refresh, never one per row; and a blocker outside the caller's scope still
// blocks, so a scoped map would under-report. The cost is therefore the whole
// store's, not the scope's: two reads and 4.9ms, best of 20, over the
// 1025-issue corpus, which keys 13 Issues (measured for qy3de.8).
func (core *Core) OpenBlockers(ctx context.Context) (map[model.ID][]model.ID, error) {
	issues, err := core.store.Issues(ctx, IssueFilter{IncludeTombstoned: true})
	if err != nil {
		return nil, err
	}
	terminal := make(map[model.ID]bool, len(issues))
	for _, issue := range issues {
		terminal[issue.ID] = issue.Tombstone == model.Tombstoned || issue.Status == model.StatusClosed
	}
	dependencies, err := core.store.Dependencies(ctx)
	if err != nil {
		return nil, err
	}
	blockers := make(map[model.ID][]model.ID)
	for _, dependency := range dependencies {
		if dependency.Tombstone == model.Tombstoned || dependency.Type != model.DepBlocks {
			continue
		}
		if terminal[dependency.FromID] {
			continue
		}
		isTerminal, known := terminal[dependency.ToID]
		if !known || !isTerminal {
			blockers[dependency.FromID] = append(blockers[dependency.FromID], dependency.ToID)
		}
	}
	return blockers, nil
}

func deferred(issue model.Issue, now time.Time) bool {
	if issue.DeferredUntil == nil {
		return false
	}
	until, err := issue.DeferredUntil.Time()
	return err == nil && until.After(now)
}

// UnblockImpacts reports how many open candidates each named blocker alone
// prevents from becoming ready.
func (core *Core) UnblockImpacts(ctx context.Context, ids []model.ID) (map[model.ID]int, error) {
	blockers, err := core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}
	wanted := make(map[model.ID]struct{}, len(ids))
	impact := make(map[model.ID]int, len(ids))
	for _, id := range ids {
		wanted[id], impact[id] = struct{}{}, 0
	}
	for _, open := range blockers {
		if len(open) != 1 {
			continue
		}
		if _, ok := wanted[open[0]]; ok {
			impact[open[0]]++
		}
	}
	return impact, nil
}

// LongestBlockerChain returns the deepest simple path of open blockers, with id
// first. Cycles terminate at the first repeated node.
func (core *Core) LongestBlockerChain(ctx context.Context, id model.ID) ([]model.ID, error) {
	if _, err := core.store.Issue(ctx, id); err != nil {
		return nil, err
	}
	graph, err := core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}
	onPath := map[model.ID]bool{}
	var walk func(model.ID) []model.ID
	walk = func(node model.ID) []model.ID {
		if onPath[node] {
			return nil
		}
		onPath[node] = true
		defer func() { onPath[node] = false }()
		best := []model.ID{}
		for _, blocker := range graph[node] {
			if candidate := walk(blocker); len(candidate) > len(best) {
				best = candidate
			}
		}
		return append([]model.ID{node}, best...)
	}
	return walk(id), nil
}

// DependencyCycles returns canonical cycles of live blocks edges.
func (core *Core) DependencyCycles(ctx context.Context) ([][]model.ID, error) {
	dependencies, err := core.store.Dependencies(ctx)
	if err != nil {
		return nil, err
	}
	graph := map[model.ID][]model.ID{}
	for _, dependency := range dependencies {
		if dependency.Type == model.DepBlocks && dependency.Tombstone == model.Live {
			graph[dependency.FromID] = append(graph[dependency.FromID], dependency.ToID)
		}
	}
	for node := range graph {
		slices.Sort(graph[node])
	}
	cycles := [][]model.ID{}
	state := map[model.ID]uint8{}
	stack := []model.ID{}
	position := map[model.ID]int{}
	var visit func(model.ID)
	visit = func(node model.ID) {
		state[node], position[node] = 1, len(stack)
		stack = append(stack, node)
		for _, next := range graph[node] {
			if state[next] == 0 {
				visit(next)
			} else if state[next] == 1 {
				// One cycle per back edge, and no two back edges can yield
				// the same one: distinct back edges end at distinct stack
				// positions, and the (from_id, to_id, dep_type) primary key
				// forbids a repeated edge. So no de-duplication is needed
				// here, and a guard for it would be a branch no input reaches.
				cycles = append(cycles, canonicalCycle(append([]model.ID(nil), stack[position[next]:]...)))
			}
		}
		stack = stack[:len(stack)-1]
		delete(position, node)
		state[node] = 2
	}
	nodes := make([]model.ID, 0, len(graph))
	for node := range graph {
		nodes = append(nodes, node)
	}
	slices.Sort(nodes)
	for _, node := range nodes {
		if state[node] == 0 {
			visit(node)
		}
	}
	slices.SortFunc(cycles, func(left, right []model.ID) int {
		return strings.Compare(fmt.Sprint(left), fmt.Sprint(right))
	})
	return cycles, nil
}

func canonicalCycle(cycle []model.ID) []model.ID {
	if len(cycle) == 0 {
		return cycle
	}
	min := 0
	for i := 1; i < len(cycle); i++ {
		if cycle[i] < cycle[min] {
			min = i
		}
	}
	return append(append([]model.ID(nil), cycle[min:]...), cycle[:min]...)
}

package tui

import (
	"bytes"
	"context"

	"github.com/tedkulp/drops/internal/core"
	"github.com/tedkulp/drops/internal/model"
	"github.com/tedkulp/drops/internal/render"
	"github.com/tedkulp/drops/internal/view"
)

// source is every read the pane makes, and the only place it touches core.
type source struct {
	core    *core.Core
	project model.Project

	// slugs is the project-key to slug map the project column reads. It is
	// loaded once: projects are not created while a pane is open, and a
	// per-refresh reload would be a second store round trip for a table of
	// fourteen rows.
	slugs map[model.ProjectKey]string
}

// rows reads one scope's row set, in the CLI's order — the store's, never
// re-sorted — annotated with each issue's open-blocker count.
//
// Two reads' worth of work, whatever the scope: the issue listing, and one
// core.OpenBlockers for the whole store. The blocker map is deliberately
// unscoped: a blocker outside the pane's scope still blocks, so a scoped map
// would under-report.
func (s *source) rows(ctx context.Context, sc scope) ([]row, error) {
	if s.slugs == nil {
		projects, err := s.core.Projects(ctx)
		if err != nil {
			return nil, err
		}
		s.slugs = make(map[model.ProjectKey]string, len(projects))
		for _, project := range projects {
			s.slugs[project.Key] = project.Slug
		}
	}

	filter := core.IssueFilter{Statuses: sc.statuses()}
	if !sc.allProjects {
		key := s.project.Key
		filter.Project = &key
	}
	issues, err := s.core.Issues(ctx, filter)
	if err != nil {
		return nil, err
	}
	blockers, err := s.core.OpenBlockers(ctx)
	if err != nil {
		return nil, err
	}

	rows := make([]row, 0, len(issues))
	for _, issue := range issues {
		rows = append(rows, row{
			id:         issue.ID,
			project:    s.slugs[issue.ProjectKey],
			status:     issue.Status,
			priority:   issue.Priority,
			title:      issue.Title,
			tombstoned: issue.Tombstone == model.Tombstoned,
			blockedBy:  len(blockers[issue.ID]),
		})
	}
	return rows, nil
}

// issue reads one issue and every relation rendered with it, in core's own
// transaction, so a page and the picker over it cannot combine two revisions
// of the graph.
//
// The pane KEEPS this view rather than re-reading for `f`: the relation picker
// lists exactly what the page beside it was drawn from, and following a
// relation costs no extra read at all.
func (s *source) issue(ctx context.Context, id model.ID) (core.IssueView, error) {
	return s.core.ViewIssue(ctx, id)
}

// page renders one already-read issue's detail text at a pane width.
//
// render.Console into a buffer, unchanged: TTY false, no pager, the measured
// width. TTY gates Rows' truncation and nothing on a page; a nil Pager writes
// straight through. The page truncates nothing at all, which is why the
// viewport that clips it has to be scrollable — those bytes are off-screen,
// not gone.
func (s *source) page(issueView core.IssueView, width int) (string, error) {
	var buf bytes.Buffer
	console := render.Console{Out: &buf, Width: width, TTY: false}
	if err := console.Page(view.Page(issueView)); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// seq is the store's write sequence: the change token the poll is built on.
//
// store_state.write_seq is bumped inside the same transaction as every
// replicated write — issues, comments, relations, labels, parents, projects,
// memories, locators — so a committed change can never be invisible to it, and
// a sync import bumps once per applied record while skipping no-op merges. It
// is one primary-key row: measured at 4.2µs against the 1025-issue corpus,
// against 5.24ms for OpenBlockers alone, so the poll costs 1/1300th of the
// refresh it decides not to make.
//
// It is deliberately COARSER than the pane: a memory write or a project rename
// moves it while nothing on screen changes. That direction is the safe one —
// it can raise a stale marker for nothing, never miss one.
func (s *source) seq(ctx context.Context) (int64, error) {
	state, err := s.core.State(ctx)
	if err != nil {
		return 0, err
	}
	return state.WriteSeq, nil
}

package tui

import (
	"fmt"
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/tedkulp/drops/internal/model"
	"github.com/tedkulp/drops/internal/render"
)

// idCap and projCap are qy3de.4's: auto-size the column to the widest value
// present, but never past twelve, and truncate what does not fit.
//
// This deliberately breaks render's "truncate what it DISPLAYS, never what
// IDENTIFIES" rule, and it is allowed to because the pane puts the full id
// back on the detail pane's border one keypress away. Measured: 44 of 46 open
// ids in `drops` are eleven columns or fewer and exactly two are 24 and 31, so
// the CLI's pad-to-widest spends twenty dead columns on 44 rows to fit two.
const (
	idCap   = 12
	projCap = 12
)

// row is one left-pane row's data, before any geometry.
type row struct {
	id         model.ID
	project    string
	status     model.Status
	priority   int
	title      string
	tombstoned bool
	// blockedBy is how many OPEN blockers this issue still has. It comes
	// from one core.OpenBlockers call per refresh, never one read per row.
	blockedBy int
}

// scope is what the row set covers: qy3de.4's `a` and `C`.
type scope struct {
	allProjects   bool
	includeClosed bool
}

// statuses is the row set's status filter. `list`'s contract, not `ready`'s:
// open AND in_progress, so the issue you are actively working on is in the
// pane you navigate from while working. `ready` structurally omits it.
func (s scope) statuses() []model.Status {
	live := []model.Status{model.StatusOpen, model.StatusInProgress}
	if s.includeClosed {
		return append(live, model.StatusClosed)
	}
	return live
}

// matches is qy3de.4's `/`: a case-insensitive literal substring over the id
// and the title. Literal rather than fuzzy because ids are structured, and
// fuzzy matching over dotted ids is noise. needle arrives lowercased.
func matches(candidate row, needle string) bool {
	if needle == "" {
		return true
	}
	return strings.Contains(strings.ToLower(string(candidate.id)), needle) ||
		strings.Contains(strings.ToLower(candidate.title), needle)
}

// matching keeps the rows matching needle, in order. It never re-sorts: the
// order is the CLI's, achieved by leaving the store's alone.
func matching(rows []row, needle string) []row {
	needle = strings.ToLower(needle)
	kept := make([]row, 0, len(rows))
	for _, candidate := range rows {
		if matches(candidate, needle) {
			kept = append(kept, candidate)
		}
	}
	return kept
}

// ready keeps the rows with no open blocker, in order. It never re-sorts,
// for the same reason matching does not: the order is the CLI's, achieved by
// leaving the store's alone.
//
// It is deliberately NOT core.Ready, and g7b23 exists because that is the
// trap. core.Ready asks the STORE a question, so it would throw away whatever
// the pane's own modes had put on screen: the closed rows `C` added, and a
// deferred issue, which core.Ready drops and this predicate keeps. (Until
// drops://8bbam it also could not see an in_progress issue at all, which is
// the row set qy3de.4 rejected for this pane; that half is fixed, and the
// reason for keeping the predicate local is not.) This is a local predicate
// over rows the pane already has — blockedBy, annotated once per refresh from
// the store-wide core.OpenBlockers — so the row set stays `list`'s contract
// under `r`, and it composes with `/`, `C` and `a` the way matching already
// does.
func ready(rows []row) []row {
	kept := make([]row, 0, len(rows))
	for _, candidate := range rows {
		if candidate.blockedBy == 0 {
			kept = append(kept, candidate)
		}
	}
	return kept
}

// cursor is the left pane's selection. It tracks an issue ID, not a row index,
// so a reload that reorders or removes rows cannot move the selection under
// the reader. position is the fallback, not the identity.
type cursor struct {
	id       model.ID
	position int
}

// restore re-finds the tracked id in a new row set. When that id is still
// present the cursor follows it wherever it moved; when it has left — filtered
// out, closed with `C` off, deleted — the cursor HOLDS the position index that
// row last occupied, clamped to the new bounds, so the reader stays where they
// were looking instead of being thrown to the top.
func (c *cursor) restore(rows []row) {
	for index, candidate := range rows {
		if candidate.id == c.id {
			c.position = index
			return
		}
	}
	if c.position >= len(rows) {
		c.position = len(rows) - 1
	}
	if c.position < 0 {
		c.position = 0
	}
	if len(rows) == 0 {
		c.id = ""
		return
	}
	c.id = rows[c.position].id
}

// move puts the cursor on one row by index, clamped.
func (c *cursor) move(rows []row, to int) {
	if len(rows) == 0 {
		c.id, c.position = "", 0
		return
	}
	c.position = min(max(to, 0), len(rows)-1)
	c.id = rows[c.position].id
}

// rowLayout is the left pane's column geometry, measured across the whole row
// set exactly once — the way render.measure does it for the CLI.
type rowLayout struct {
	idPad   int
	projPad int // zero when the project column is off
	width   int
}

// measureRows sizes the columns to the widest value present, capped.
func measureRows(rows []row, showProject bool, width int) rowLayout {
	measured := rowLayout{width: width}
	for _, candidate := range rows {
		measured.idPad = max(measured.idPad, render.Cols(string(candidate.id)))
		if showProject {
			measured.projPad = max(measured.projPad, render.Cols(candidate.project))
		}
	}
	measured.idPad = min(measured.idPad, idCap)
	measured.projPad = min(measured.projPad, projCap)
	return measured
}

// lead is everything left of the title: the CLI's row minus its type column.
// Eight columns to say `task` on a pane whose whole job is navigation, with
// the detail pane one keypress away, is the cheapest eight columns to spend.
//
// The glyphs stay render's, so a listing and a page can never disagree about
// what a state looks like.
func (measured rowLayout) lead(candidate row) string {
	lead := fmt.Sprintf("%s %-*s P%d",
		render.StatusMark(candidate.status, candidate.tombstoned),
		measured.idPad, render.Ellipsis(string(candidate.id), measured.idPad),
		candidate.priority)
	if measured.projPad > 0 {
		lead += fmt.Sprintf(" %-*s", measured.projPad, render.Ellipsis(candidate.project, measured.projPad))
	}
	return lead
}

// marker is how a blocked row says so: four columns, not thirteen.
//
// qy3de.5 measured the alternatives on the 13 blocked rows of the corpus. At
// 80 columns with the project column on, the pane is 38 wide and the lead is
// 31, so a 13-column " blocked by N" leaves NEGATIVE room and all 13 rows
// render with no title at all. A rule that drops the long form under pressure
// was rejected for a different reason: qy3de.4 denied a ready-only key BECAUSE
// the row already carries this, and a marker that disappears when the pane is
// crowded cannot carry that argument. g7b23 has since given that key out on a
// real-use observation, which does not weaken the argument here: the marker is
// what tells you the rows `r` would hide are there at all.
func marker(candidate row) string {
	if candidate.blockedBy == 0 {
		return ""
	}
	return fmt.Sprintf(" [%d]", candidate.blockedBy)
}

// line composes one row.
//
// The marker is appended AFTER the title is cut, never reserved before it —
// euv2e.4 recorded that trap and it is paid for here. The cut itself goes
// through render.Ellipsis rather than a second implementation of the same
// rule.
func (measured rowLayout) line(candidate row) string {
	lead := measured.lead(candidate)
	mark := marker(candidate)
	title := render.Ellipsis(candidate.title, measured.width-render.Cols(lead)-1-render.Cols(mark))
	if title == "" {
		return lead + mark
	}
	return lead + " " + title + mark
}

// listBody renders the visible window of rows into exactly height lines,
// scrolled so the cursor is on screen.
func listBody(rows []row, selected, width, height int, showProject bool, empty string) string {
	if len(rows) == 0 {
		return pad(dimStyle.Render(render.Ellipsis(empty, width)), width, height)
	}
	measured := measureRows(rows, showProject, width)

	top := 0
	if selected >= height {
		top = selected - height + 1
	}
	top = max(0, min(top, len(rows)-height))

	lines := make([]string, 0, height)
	for index := top; index < len(rows) && len(lines) < height; index++ {
		line := measured.line(rows[index])
		// Padded to the full width before styling, so the cursor's reverse
		// video covers the whole row rather than stopping at the title.
		line += strings.Repeat(" ", max(0, width-lipgloss.Width(line)))
		if index == selected {
			line = cursorStyle.Render(line)
		}
		lines = append(lines, line)
	}
	return pad(strings.Join(lines, "\n"), width, height)
}

