package tui

// THROWAWAY measurement for tedkulp/drops#4. Delete after recording numbers.

import (
	"context"
	"os"
	"slices"
	"testing"

	"github.com/tedkulp/drops/internal/core"
	"github.com/tedkulp/drops/internal/model"
	"github.com/tedkulp/drops/internal/store"
)

func benchSetup(b *testing.B) (*core.Core, *store.Store, model.Project) {
	path := os.Getenv("BOARD_BENCH_DB")
	if path == "" {
		b.Skip("BOARD_BENCH_DB unset")
	}
	ctx := context.Background()
	opened, err := store.Open(ctx, path)
	if err != nil {
		b.Fatal(err)
	}
	b.Cleanup(func() { opened.Close() })
	replica, _ := model.ParseReplicaKey("aaaaaaaaaaaaaaaaaaaaaaaaae")
	c := core.New(opened, replica, nil, nil, func(core.Warning) {})
	project, err := c.ProjectBySlug(ctx, "drops")
	if err != nil {
		b.Fatal(err)
	}
	return c, opened, project
}

func BenchmarkBoardReads(b *testing.B) {
	c, st, project := benchSetup(b)
	ctx := context.Background()
	key := project.Key
	live := []model.Status{model.StatusOpen, model.StatusInProgress}
	all := append(slices.Clone(live), model.StatusClosed)

	issuesAll, _ := c.Issues(ctx, core.IssueFilter{Project: &key, Statuses: all})
	ids := make([]model.ID, len(issuesAll))
	for i, issue := range issuesAll {
		ids[i] = issue.ID
	}
	b.Logf("scoped issues incl closed: %d", len(issuesAll))

	b.Run("IssuesLive", func(b *testing.B) {
		for b.Loop() {
			_, _ = c.Issues(ctx, core.IssueFilter{Project: &key, Statuses: live})
		}
	})
	b.Run("IssuesWithClosed", func(b *testing.B) {
		for b.Loop() {
			_, _ = c.Issues(ctx, core.IssueFilter{Project: &key, Statuses: all})
		}
	})
	b.Run("OpenBlockers", func(b *testing.B) {
		for b.Loop() {
			_, _ = c.OpenBlockers(ctx)
		}
	})
	b.Run("UnblockImpactsAllIDs", func(b *testing.B) {
		for b.Loop() {
			_, _ = c.UnblockImpacts(ctx, ids)
		}
	})
	b.Run("StoreLabelsAll", func(b *testing.B) {
		for b.Loop() {
			_, _ = st.Labels(ctx)
		}
	})
	b.Run("ClosedLocalSort", func(b *testing.B) {
		for b.Loop() {
			closed := make([]model.Issue, 0, len(issuesAll))
			for _, issue := range issuesAll {
				if issue.Status == model.StatusClosed {
					closed = append(closed, issue)
				}
			}
			slices.SortStableFunc(closed, func(l, r model.Issue) int {
				return -compareTS(l.ClosedAt, r.ClosedAt)
			})
		}
	})
	b.Run("WholeBoardRefresh", func(b *testing.B) {
		for b.Loop() {
			issues, _ := c.Issues(ctx, core.IssueFilter{Project: &key, Statuses: all})
			blockers, _ := c.OpenBlockers(ctx)
			labels, _ := st.Labels(ctx)
			byIssue := map[model.ID][]string{}
			for _, l := range labels {
				if l.Tombstone == model.Live {
					byIssue[l.IssueID] = append(byIssue[l.IssueID], l.Name)
				}
			}
			impact := map[model.ID]int{}
			for _, open := range blockers {
				if len(open) == 1 {
					impact[open[0]]++
				}
			}
			_ = issues
		}
	})
}

func compareTS(l, r *model.Timestamp) int {
	switch {
	case l == nil && r == nil:
		return 0
	case l == nil:
		return -1
	case r == nil:
		return 1
	}
	lt, _ := l.Time()
	rt, _ := r.Time()
	return lt.Compare(rt)
}

